/**
 * 智谱视觉识别功能
 * 独立脚本文件，兼容 Chrome 扩展 CSP 策略
 */
(function() {
    'use strict';
    
    // 等待 DOM 加载完成
    function initZhipuRecognition() {
        // 注入识别结果样式
        var style = document.createElement('style');
        style.textContent = [
            '.zhipu-result {',
            '    margin: 8px 0;',
            '    padding: 10px;',
            '    background: linear-gradient(135deg, #f0f4ff, #e8ecff);',
            '    border-radius: 8px;',
            '    font-size: 12px;',
            '    line-height: 1.5;',
            '    border-left: 4px solid #667eea;',
            '    color: #333;',
            '}',
            '.zhipu-result .result-title {',
            '    font-weight: 600;',
            '    margin-bottom: 6px;',
            '    color: #667eea;',
            '}',
            '.zhipu-result .result-content {',
            '    color: #444;',
            '}',
            '.zhipu-toast {',
            '    position: fixed; top: 20px; left: 50%; transform: translateX(-50%); z-index: 10001;',
            '    background: rgba(0,0,0,0.8); color: #fff; padding: 12px 24px;',
            '    border-radius: 20px; font-size: 14px; white-space: nowrap;',
            '    animation: toastFade 2s ease forwards;',
            '}',
            '@keyframes toastFade { 0% { opacity: 0; transform: translateX(-50%) translateY(-10px); } 15% { opacity: 1; transform: translateX(-50%) translateY(0); } 85% { opacity: 1; } 100% { opacity: 0; } }',
            '@media (prefers-color-scheme: dark) {',
            '    .zhipu-result {',
            '        background: linear-gradient(135deg, #2a2a4a, #1e1e3a);',
            '        border-left-color: #8b9dff;',
            '    }',
            '    .zhipu-result .result-title {',
            '        color: #a5b4fc;',
            '    }',
            '    .zhipu-result .result-content {',
            '        color: #e0e0e0;',
            '    }',
            '    .zhipu-toast { background: rgba(255,255,255,0.9); color: #333; }',
            '}'
        ].join('');
        document.head.appendChild(style);
        
        // 加载智谱配置
        ZhipuVision.loadConfig().then(function() {
            var config = ZhipuVision.getConfig();
            
            var zhipuBtn = document.getElementById('zhipuRecognizeBtn');
            var stepsList = document.getElementById('stepsList');
            
            if (!zhipuBtn || !stepsList) {
                console.error('智谱识别按钮或步骤列表未找到');
                return;
            }
            
            // Toast提示函数
                        function showToast(msg) {
                            var t = document.createElement('div');
                            t.className = 'zhipu-toast';
                            t.textContent = msg;
                            document.body.appendChild(t);
                            setTimeout(function() { t.remove(); }, 2000);
                        }
                        
                        // 监听配置变化 - 每2秒检查一次
            setInterval(function() {
                ZhipuVision.loadConfig();
            }, 2000);
            
            // 智谱识别按钮点击事件
            zhipuBtn.addEventListener('click', async function() {
                // 禁用按钮防止重复点击
                zhipuBtn.disabled = true;
                zhipuBtn.innerText = '稍等';
                
                if (!ZhipuVision.isConfigured()) {
                    ZhipuVision.showResultDialog('提示', '请先在设置中配置智谱 API Key');
                    zhipuBtn.disabled = false;
                    zhipuBtn.innerText = 'AI撰写';
                    return;
                }
                
                // 获取所有截图
                var stepElements = stepsList.querySelectorAll('li');
                if (stepElements.length === 0) {
                    showToast('暂无截图可识别');
                    zhipuBtn.disabled = false;
                    zhipuBtn.innerText = 'AI撰写';
                    return;
                }
                
                // 检查是否有文本步骤 - 如果有，交给 text-step.min.js 处理
                var hasTextSteps = Array.from(stepElements).some(function(step) {
                    return step.classList.contains('step-text-only');
                });
                if (hasTextSteps) {
                    zhipuBtn.disabled = false;
                    zhipuBtn.innerText = 'AI撰写';
                    return;
                }
                
                // 收集图片数据
                var images = [];
                var imageElements = [];
                
                stepElements.forEach(function(step, index) {
                    var img = step.querySelector('img');
                    if (img && img.src) {
                        images.push(img.src);
                        imageElements.push({ index: index, element: step });
                    }
                });
                
                if (images.length === 0) {
                    showToast('没有找到可识别的图片');
                    zhipuBtn.disabled = false;
                    zhipuBtn.innerText = 'AI撰写';
                    return;
                }
                
                // 获取最新配置
                await ZhipuVision.loadConfig();
                var config = ZhipuVision.getConfig();
                
                // 询问是否使用自定义提示词
                ZhipuVision.showPromptDialog(config.defaultPrompt, async function(customPrompt) {
                    // 显示进度条并滚动到顶部
                    var zhipuProgress = document.getElementById('zhipuProgress');
                    var zhipuProgressBar = document.getElementById('zhipuProgressBar');
                    var zhipuProgressText = document.getElementById('zhipuProgressText');
                    var zhipuProgressTitle = document.getElementById('zhipuProgressTitle');
                    
                    zhipuProgress.style.display = 'block';
                    zhipuProgressTitle.textContent = '智谱识别中...';
                    zhipuProgressBar.style.width = '0%';
                    zhipuProgressText.textContent = '正在识别第 1/' + images.length + ' 张图片';
                    
                    // 滚动到顶部显示进度条
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                    
                    var successCount = 0;
                    var failCount = 0;
                    var recognitionResults = {};
                    
                    for (var i = 0; i < images.length; i++) {
                        // 更新进度
                        var percent = Math.round((i / images.length) * 100);
                        zhipuProgressBar.style.width = percent + '%';
                        zhipuProgressText.textContent = '正在识别第 ' + (i + 1) + '/' + images.length + ' 张图片';
                        
                        try {
                            var result = await ZhipuVision.recognizeImage(images[i], customPrompt);
                            successCount++;
                            
                            // 将识别结果添加到步骤中（图片下方）
                            var stepItem = imageElements[i].element;
                            var imgContainer = stepItem.querySelector('div[style*="position: relative"][style*="display: inline-block"]');
                            var zhipuResult = result.choices && result.choices[0] && result.choices[0].message ? result.choices[0].message.content : '';
                            
                            if (zhipuResult) {
                                // 保存识别结果到 storage（用于导出）
                                recognitionResults[i] = zhipuResult;
                                
                                // 移除旧结果
                                var oldResult = stepItem.querySelector('.zhipu-result');
                                if (oldResult) oldResult.remove();
                                
                                // 创建新结果容器
                                var resultDiv = document.createElement('div');
                                resultDiv.className = 'zhipu-result';
                                resultDiv.innerHTML = '<div class="result-title">智谱识别结果</div><div class="result-content">' + zhipuResult + '</div>';
                                
                                // 插入到图片容器之后
                                if (imgContainer && imgContainer.nextSibling) {
                                    stepItem.insertBefore(resultDiv, imgContainer.nextSibling);
                                } else if (imgContainer) {
                                    imgContainer.parentNode.insertBefore(resultDiv, imgContainer.nextSibling);
                                } else {
                                    stepItem.appendChild(resultDiv);
                                }
                            }
                        } catch (error) {
                            failCount++;
                        }
                    }
                    
                    // 完成进度条
                    zhipuProgressBar.style.width = '100%';
                    
                    // 保存识别结果到 storage（用于导出）
                    if (Object.keys(recognitionResults).length > 0) {
                        chrome.storage.local.set({ zhipuRecognitionResults: recognitionResults });
                    }
                    
                    // 显示完成结果
                    setTimeout(function() {
                        zhipuProgressTitle.textContent = '识别完成';
                        zhipuProgressText.textContent = '成功：' + successCount + ' 张 | 失败：' + failCount + ' 张';
                        
                        // 恢复按钮状态
                        zhipuBtn.disabled = false;
                        zhipuBtn.innerText = 'AI撰写';
                        
                        // 3秒后隐藏
                        setTimeout(function() {
                            zhipuProgress.style.display = 'none';
                        }, 3000);
                    }, 500);
                });
            });
        });
    }
    
    // DOM 加载完成后初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initZhipuRecognition);
    } else {
        initZhipuRecognition();
    }
})();
